"""FastAPI service for database-backed CO2 forecasting."""import osfrom contextlib import asynccontextmanagerfrom datetime import datetimefrom pathlib import Pathfrom fastapi import FastAPI, HTTPExceptionfrom pydantic import BaseModel, Field, model_validatorfrom sqlalchemy import func, select, textfrom co2_submission.deployment.database import (    Experiment,    ProcessMeasurement,    get_engine,    get_session_factory,)from co2_submission.deployment.inference import ForecasterServicefrom co2_submission.deployment.repository import (    load_experiment_from_database,)PROJECT_ROOT = Path(__file__).resolve().parents[1]CHECKPOINT = Path(    os.getenv(        "MODEL_CHECKPOINT",        str(PROJECT_ROOT / "results/final_test/final_model.pt"),    ))@asynccontextmanagerasync def lifespan(app: FastAPI):    app.state.forecaster = ForecasterService(CHECKPOINT)    yieldapp = FastAPI(    title="CO2 Transformer Forecasting API",    description=(        "Database-backed forecasting of CO2 concentrations "        "at six absorber sampling locations."    ),    version="1.0.0",    lifespan=lifespan,)class PredictionRequest(BaseModel):    experiment: str    origin_row: int | None = Field(default=None, ge=0)    timestamp: datetime | None = None    @model_validator(mode="after")    def validate_origin(self):        if (self.origin_row is None) == (self.timestamp is None):            raise ValueError(                "Provide exactly one of origin_row or timestamp."            )        return selfclass WindowRequest(BaseModel):    experiment: str    start_timestamp: datetime    end_timestamp: datetime    @model_validator(mode="after")    def validate_window(self):        if self.start_timestamp > self.end_timestamp:            raise ValueError(                "start_timestamp must not exceed end_timestamp."            )        return selfdef resolve_origin(experiment_name, origin_row=None, timestamp=None):    """Resolve a requested origin using PostgreSQL records."""    Session = get_session_factory()    with Session() as session:        experiment = session.scalar(            select(Experiment).where(                Experiment.name == experiment_name            )        )        if experiment is None:            raise HTTPException(                status_code=404,                detail=f"Experiment not found: {experiment_name}",            )        if origin_row is not None:            row = session.scalar(                select(ProcessMeasurement).where(                    ProcessMeasurement.experiment_id == experiment.id,                    ProcessMeasurement.row_index == origin_row,                )            )        else:            row = session.scalar(                select(ProcessMeasurement)                .where(                    ProcessMeasurement.experiment_id == experiment.id,                    ProcessMeasurement.timestamp == timestamp,                )                .order_by(ProcessMeasurement.row_index)                .limit(1)            )        if row is None:            raise HTTPException(                status_code=404,                detail="Requested forecast origin was not found.",            )        return row.row_indexdef predict_at_origin(app, experiment, origin_row):    """Execute the verified database-backed inference pipeline."""    forecaster = app.state.forecaster    if origin_row < forecaster.history - 1:        raise HTTPException(            status_code=422,            detail=(                f"At least {forecaster.history} historical "                "measurements are required."            ),        )    frame = load_experiment_from_database(        experiment,        origin_row=origin_row,    )    try:        result = forecaster.predict_at_row(frame, origin_row)    except ValueError as exc:        raise HTTPException(            status_code=422,            detail=str(exc),        ) from exc    return {        "experiment": experiment,        **result,    }@app.get("/health")def health():    try:        with get_engine().connect() as connection:            connection.execute(text("SELECT 1"))    except Exception as exc:        raise HTTPException(            status_code=503,            detail="Database unavailable",        ) from exc    return {        "status": "ok",        "database": "connected",        "model": "loaded",    }@app.get("/experiments")def list_experiments():    Session = get_session_factory()    with Session() as session:        rows = session.execute(            select(                Experiment.name,                func.count(ProcessMeasurement.id),            )            .outerjoin(                ProcessMeasurement,                ProcessMeasurement.experiment_id == Experiment.id,            )            .group_by(Experiment.name)            .order_by(Experiment.name)        ).all()    return [        {"experiment": name, "rows": count}        for name, count in rows    ]@app.post("/predict")def predict(request: PredictionRequest):    origin_row = resolve_origin(        request.experiment,        origin_row=request.origin_row,        timestamp=request.timestamp,    )    return predict_at_origin(        app,        request.experiment,        origin_row,    )@app.post("/predict/window")def predict_window(request: WindowRequest):    Session = get_session_factory()    with Session() as session:        experiment = session.scalar(            select(Experiment).where(                Experiment.name == request.experiment            )        )        if experiment is None:            raise HTTPException(                status_code=404,                detail="Experiment not found.",            )        origins = session.scalars(            select(ProcessMeasurement.row_index)            .where(                ProcessMeasurement.experiment_id == experiment.id,                ProcessMeasurement.timestamp >= request.start_timestamp,                ProcessMeasurement.timestamp <= request.end_timestamp,            )            .order_by(ProcessMeasurement.row_index)        ).all()    if not origins:        raise HTTPException(            status_code=404,            detail="No measurements found in the requested window.",        )    forecaster = app.state.forecaster    eligible_origins = [        origin        for origin in origins        if origin >= forecaster.history - 1    ]    if not eligible_origins:        raise HTTPException(            status_code=422,            detail="No origins have sufficient historical measurements.",        )    predictions = [        predict_at_origin(app, request.experiment, origin)        for origin in eligible_origins    ]    return {        "experiment": request.experiment,        "count": len(predictions),        "predictions": predictions,    }